/* Plotboard — 落位即意图 · placement is intent
   Dark floor-canvas theme. Tokens below are the whole design system. */

:root {
  --bg: #0e1116;
  --panel: #151a21;
  --panel-2: #1a2029;
  --border: #272f3b;
  --border-soft: #212833;
  --text: #e8ecf3;
  --muted: #9aa5b5;
  --accent: #ffb454;          /* amber — action & selection */
  --accent-dim: #b57c31;
  --link: #7aa2f7;            /* relation lines */
  --danger: #e06c75;
  --tile-bg: #232a35;
  --tile-border: #35404f;
  --tile-bg-hover: #2a3240;
  /* zone palette, index-aligned with app.js PALETTE */
  --z0: #5b8def; --z1: #3fbf8f; --z2: #e8a33d; --z3: #8d7ae5;
  --z4: #4fc3dd; --z5: #c973b8; --z6: #9ccc50; --z7: #e06c75;
  --grid-minor: rgba(255,255,255,0.045);
  --grid-major: rgba(255,255,255,0.09);
  --radius: 8px;
  --font: "Segoe UI", system-ui, -apple-system, "Noto Sans SC", sans-serif;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
  display: grid;
  grid-template-rows: auto 1fr auto;
  overflow: hidden;
}

kbd {
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1;
  padding: 3px 5px;
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--panel-2);
  color: var(--muted);
}
.mut { color: var(--muted); }

button {
  font: inherit;
  color: var(--text);
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 10px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
button:hover { background: #222a35; border-color: #35404f; }
button:focus-visible, [tabindex]:focus-visible, input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
button[aria-pressed="true"] {
  border-color: var(--accent-dim);
  color: var(--accent);
}

/* ---------- title bar ---------- */
#titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 9px 14px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.brand-mark {
  width: 12px; height: 12px; border-radius: 3px;
  background: linear-gradient(135deg, var(--accent) 0 50%, var(--link) 50% 100%);
  align-self: center;
}
.brand h1 { font-size: 16px; font-weight: 650; letter-spacing: 0.2px; }
.tagline { font-size: 12px; color: var(--muted); white-space: nowrap; }
.toolbar { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.toolbar .sep { width: 1px; height: 20px; background: var(--border); margin: 0 4px; }
.zoom-label { min-width: 56px; justify-content: center; font-family: var(--mono); font-size: 12px; }
#btnReset.confirm { border-color: var(--danger); color: var(--danger); }

/* ---------- layout ---------- */
#layout {
  display: grid;
  grid-template-columns: 216px minmax(0, 1fr) 268px;
  min-height: 0;
}

/* ---------- zone rail ---------- */
#rail {
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 12px;
  overflow-y: auto;
}
#rail h2 {
  font-size: 11px; font-weight: 600; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--muted); margin-bottom: 10px;
}
#zoneList { list-style: none; display: grid; gap: 4px; }
.zone-row {
  width: 100%;
  display: flex; align-items: center; gap: 8px;
  padding: 7px 9px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  text-align: left;
  font: inherit;
  color: var(--text);
}
.zone-row:hover { background: var(--panel-2); border-color: var(--border-soft); }
.zone-row.selected { border-color: var(--z-dot, var(--border)); background: var(--panel-2); }
.z-dot {
  width: 10px; height: 10px; border-radius: 3px; flex: none;
  background: var(--z-dot, transparent);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.12) inset;
}
.z-dot.hollow { background: transparent; border: 1.5px dashed var(--muted); box-shadow: none; }
.zone-row .z-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.zone-row .z-count { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.floor-row {
  display: flex; align-items: center; gap: 8px;
  margin-top: 4px; padding: 7px 9px;
  border-top: 1px solid var(--border-soft);
  color: var(--muted); font-size: 13px;
}
.floor-row .z-count { margin-left: auto; font-family: var(--mono); font-size: 12px; }
.rail-hint { margin-top: 14px; font-size: 12px; color: var(--muted); line-height: 1.7; }

/* ---------- viewport / world ---------- */
#viewport {
  position: relative;
  overflow: hidden;
  min-width: 0;
  background-color: #12161c;
  background-image:
    linear-gradient(var(--grid-major) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-major) 1px, transparent 1px),
    linear-gradient(var(--grid-minor) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-minor) 1px, transparent 1px);
  cursor: default;
}
#viewport.panning { cursor: grabbing; }
#world { position: absolute; left: 0; top: 0; transform-origin: 0 0; }

/* zones */
.zone {
  position: absolute;
  border: 1.5px solid color-mix(in srgb, var(--zc) 55%, transparent);
  background: color-mix(in srgb, var(--zc) 9%, transparent);
  border-radius: 6px;
  pointer-events: none; /* only the chip is interactive */
}
.zone.landed {
  border-color: var(--zc);
  border-width: 2px;
  background: color-mix(in srgb, var(--zc) 16%, transparent);
}
.zone-chip {
  position: absolute;
  left: -1.5px; top: -1.5px;
  transform: translateY(-100%);
  border: 1px solid color-mix(in srgb, var(--zc) 70%, transparent);
  border-bottom-left-radius: 0; border-bottom-right-radius: 0;
  border-bottom: none;
  padding: 2px 8px 3px;
  background: color-mix(in srgb, var(--zc) 22%, #10131a);
  font-size: 12px;
  color: var(--text);
  gap: 7px;
  pointer-events: auto;
  max-width: 240px;
}
.zone-chip:hover { background: color-mix(in srgb, var(--zc) 34%, #10131a); }
.zone-chip .z-count { font-family: var(--mono); font-size: 11px; color: var(--muted); }
.zone-chip kbd { padding: 1px 4px; font-size: 10px; }
.zone-chip .z-chip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* tiles */
.tile {
  position: absolute;
  width: 96px; height: 64px;
  background: var(--tile-bg);
  border: 1px solid var(--tile-border);
  border-radius: var(--radius);
  display: flex; align-items: center; justify-content: center;
  padding: 8px;
  cursor: grab;
  box-shadow: 0 2px 6px rgba(0,0,0,0.35);
  user-select: none;
}
.tile:hover { background: var(--tile-bg-hover); border-color: #46536a; }
.tile:active { cursor: grabbing; }
.tile.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent), 0 4px 14px rgba(255,180,84,0.18);
  z-index: 5;
}
.t-name {
  font-size: 12px; line-height: 1.25; text-align: center;
  overflow: hidden; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
  word-break: break-word;
}
.t-dot {
  position: absolute; top: -5px; right: -5px;
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--zc, transparent);
  border: 2px solid #12161c;
}
.t-dot.hollow { background: var(--tile-bg); border: 2px dashed var(--muted); }

/* fx: relation link, ghost */
#fxLayer { position: absolute; left: 0; top: 0; }
.link {
  position: absolute; height: 0;
  border-top: 2px dashed color-mix(in srgb, var(--link) 75%, transparent);
  transform-origin: 0 0;
  pointer-events: none;
}
.link-label {
  position: absolute;
  transform: translate(-50%, -130%);
  font-family: var(--mono); font-size: 10px;
  color: var(--link);
  background: #12161ccc;
  padding: 1px 5px; border-radius: 4px;
  border: 1px solid color-mix(in srgb, var(--link) 40%, transparent);
  pointer-events: none;
  white-space: nowrap;
}
.ghost {
  position: absolute;
  border: 2px dashed var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: var(--radius);
  pointer-events: none;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; color: var(--accent);
  letter-spacing: 0.08em;
}

/* empty state */
#emptyState {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; gap: 10px;
  align-items: center; justify-content: center;
  pointer-events: none;
  color: var(--muted);
  text-align: center;
}
#emptyState .empty-title { font-size: 18px; color: var(--text); }
#emptyState kbd { margin: 0 2px; }

/* rename input */
.rename-input {
  position: absolute;
  z-index: 50;
  font-family: var(--font);
  font-size: 12px;
  text-align: center;
  color: var(--text);
  background: #10141b;
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  padding: 4px;
}

/* ---------- inspector ---------- */
#inspector {
  background: var(--panel);
  border-left: 1px solid var(--border);
  padding: 14px;
  overflow-y: auto;
  font-size: 13px;
}
#inspector h2 {
  font-size: 11px; font-weight: 600; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--muted); margin-bottom: 10px;
}
.insp-title { font-size: 15px; font-weight: 650; margin-bottom: 2px; word-break: break-word; }
.insp-kind { font-size: 11px; color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; margin-bottom: 14px; }
.fact { display: flex; align-items: baseline; gap: 8px; padding: 7px 0; border-top: 1px solid var(--border-soft); }
.fact dt { width: 74px; flex: none; color: var(--muted); font-size: 12px; }
.fact dd { flex: 1; min-width: 0; font-family: var(--mono); font-size: 12px; overflow-wrap: break-word; }
.fact dd .z-dot { display: inline-block; vertical-align: -1px; margin-right: 6px; }
.insp-note { margin-top: 14px; font-size: 12px; line-height: 1.6; color: var(--muted); border-left: 2px solid var(--border); padding-left: 10px; }
.insp-actions { display: flex; gap: 8px; margin-top: 16px; flex-wrap: wrap; }
.insp-actions .danger { border-color: #5a3136; color: var(--danger); }
.insp-actions .danger:hover { border-color: var(--danger); }
.insp-empty .fact { border-top: none; }
.insp-kbd-list { display: grid; gap: 8px; margin-top: 10px; }
.insp-kbd-list div { display: flex; gap: 8px; align-items: baseline; color: var(--muted); font-size: 12.5px; }
.badge-count { font-family: var(--mono); }

/* ---------- status bar ---------- */
#statusbar {
  display: flex; align-items: center; gap: 18px;
  padding: 6px 14px;
  background: var(--panel);
  border-top: 1px solid var(--border);
  font-family: var(--mono);
  font-size: 12px;
  color: var(--muted);
}
#statusHint { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#statusHint .landing { color: var(--accent); }
#statusHint .flash { color: var(--link); }
#statusCoords { white-space: nowrap; }
#statusStats { white-space: nowrap; display: flex; align-items: center; gap: 10px; }
#statusStats .warn { color: var(--danger); }

/* ---------- help overlay ---------- */
#helpOverlay {
  position: fixed; inset: 0; z-index: 100;
  background: rgba(6,8,12,0.72);
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
}
.help-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  max-width: 860px; width: 100%;
  max-height: 100%;
  overflow-y: auto;
  padding: 18px 20px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}
.help-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.help-head h2 { font-size: 16px; }
.help-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 6px 26px; }
.help-grid h3 {
  font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--accent); margin: 10px 0 8px;
}
.help-grid dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; align-items: baseline; }
.help-grid dt { white-space: nowrap; }
.help-grid dd { color: var(--muted); font-size: 12.5px; }
.help-foot { margin-top: 16px; padding-top: 12px; border-top: 1px solid var(--border-soft); font-size: 12.5px; line-height: 1.6; color: var(--muted); }

[hidden] { display: none !important; }

@media (max-width: 980px) {
  #layout { grid-template-columns: 180px minmax(0,1fr) 220px; }
  .tagline { display: none; }
}

