    if (e.key === "w" || e.key === "W") { e.preventDefault(); panBy(0, panStep); return; }
    if (e.key === "s" || e.key === "S") { e.preventDefault(); panBy(0, -panStep); return; }
    if (e.key === "a" || e.key === "A") { e.preventDefault(); panBy(panStep, 0); return; }
