1	/* Plotboard — 落位即意图 · placement is intent
2	   A spatial workspace: land objects into zones; position is the only source of truth.
3	   Every spatial operation has a keyboard equivalent (acceptance seed). */
4	(function () {
5	  "use strict";
6	
7	  // ---------- constants ----------
8	  var G = 20;             // grid unit (world px)
9	  var OBJ_W = 96, OBJ_H = 64;
10	  var REGION_W = 360, REGION_H = 240;
11	  var ZOOM_MIN = 0.25, ZOOM_MAX = 2.5;
12	  var STORE_KEY = "plotboard.v1";
13	  var PALETTE = ["#5b8def", "#3fbf8f", "#e8a33d", "#8d7ae5", "#4fc3dd", "#c973b8", "#9ccc50", "#e06c75"];
14	
15	  // ---------- initial scene (inlined: first paint is immediately usable) ----------
16	  function scene() {
17	    return {
18	      seq: 114,
19	      regions: [
20	        { id: "z1", name: "Entrance Hall", x: 80,  y: 80,  w: 480, h: 360 },
21	        { id: "z2", name: "Main Gallery",  x: 600, y: 80,  w: 560, h: 540 },
22	        { id: "z3", name: "North Wing",    x: 80,  y: 480, w: 480, h: 340 },
23	        { id: "z4", name: "Archive",       x: 1200, y: 80, w: 320, h: 540 }
24	      ],
25	      objects: [
26	        { id: "o1",  name: "Ticket Desk",  x: 120, y: 120 },
27	        { id: "o2",  name: "Info Panel",   x: 120, y: 220 },
28	        { id: "o3",  name: "Coat Check",   x: 300, y: 120 },
29	        { id: "o4",  name: "Bronze Helm",  x: 660, y: 140 },
30	        { id: "o5",  name: "Stone Stele",  x: 660, y: 300 },
31	        { id: "o6",  name: "Tapestry",     x: 900, y: 140 },
32	        { id: "o7",  name: "Vitrine Set",  x: 900, y: 300 },
33	        { id: "o8",  name: "Prints Rack",  x: 120, y: 540 },
34	        { id: "o9",  name: "Sketch Wall",  x: 300, y: 540 },
35	        { id: "o10", name: "Prep Table",   x: 120, y: 680 },
36	        { id: "o11", name: "Crate 7",      x: 1260, y: 140 },
37	        { id: "o12", name: "Flat File",    x: 1260, y: 300 },
38	        { id: "o13", name: "Rolling Cart", x: 660, y: 700 }
39	      ]
40	    };
41	  }
42	
43	  // ---------- state ----------
44	  var state = {
45	    seq: 0,
46	    regions: [],
47	    objects: [],
48	    sel: null,        // {kind:'object'|'region', id} — primary selection
49	    selMany: null,    // [ids] when select-all is active
50	    placing: null,    // {kind:'object'|'region', x, y}
51	    renaming: null,   // {kind, id}
52	    snap: true,
53	    zoom: 1, panX: 0, panY: 0,
54	    cursor: null,     // {x, y} world
55	    landing: null,    // region id under ghost / dragged selection
56	    flash: null,      // transient status message
57	    storageOK: true
58	  };
59	
60	  // ---------- dom ----------
61	  var $ = function (id) { return document.getElementById(id); };
62	  var viewport, world, zoneLayer, objLayer, fxLayer, ghost, emptyState;
63	  var zoneListEl, floorRowEl, inspectorEl;
64	  var statusHint, statusCoords, statusStats;
65	  var helpOverlay, btnReset, btnSnap, btnZoomLabel;
66	
67	  // ---------- helpers ----------
68	  function snap(v) { return state.snap ? Math.round(v / G) * G : Math.round(v); }
69	  function byId(kind, id) {
70	    var arr = kind === "region" ? state.regions : state.objects;
71	    for (var i = 0; i < arr.length; i++) if (arr[i].id === id) return arr[i];
72	    return null;
73	  }
74	  function objSize() { return { w: OBJ_W, h: OBJ_H }; }
75	  function centerOf(o) {
76	    var s = o.w ? o : { w: OBJ_W, h: OBJ_H };
77	    return { x: o.x + s.w / 2, y: o.y + s.h / 2 };
78	  }
79	  function zoneAt(cx, cy) {
80	    for (var i = 0; i < state.regions.length; i++) {
81	      var r = state.regions[i];
82	      if (cx >= r.x && cx <= r.x + r.w && cy >= r.y && cy <= r.y + r.h) return r;
83	    }
84	    return null;
85	  }
86	  function zoneOf(o) { var c = centerOf(o); return zoneAt(c.x, c.y); }
87	  function zoneColor(i) { return PALETTE[i % PALETTE.length]; }
88	  function zoneIndex(id) {
89	    for (var i = 0; i < state.regions.length; i++) if (state.regions[i].id === id) return i;
90	    return -1;
91	  }
92	  function nearestTo(o) {
93	    var c1 = centerOf(o), best = null, bd = Infinity;
94	    for (var i = 0; i < state.objects.length; i++) {
95	      var t = state.objects[i];
96	      if (t.id === o.id) continue;
97	      var c2 = centerOf(t);
98	      var d = Math.hypot(c2.x - c1.x, c2.y - c1.y);
99	      if (d < bd) { bd = d; best = t; }
100	    }
101	    return best ? { obj: best, dist: bd } : null;
102	  }
103	  function overlaps(x, y, w, h, ignoreId) {
104	    for (var i = 0; i < state.objects.length; i++) {
105	      var o = state.objects[i];
106	      if (o.id === ignoreId) continue;
107	      if (x < o.x + OBJ_W && x + w > o.x && y < o.y + OBJ_H && y + h > o.y) return true;
108	    }
109	    return false;
110	  }
111	  function findSlot(region, ignoreId) {
112	    for (var y = region.y + G; y + OBJ_H <= region.y + region.h - G / 2; y += G) {
113	      for (var x = region.x + G; x + OBJ_W <= region.x + region.w - G / 2; x += G) {
114	        if (!overlaps(x, y, OBJ_W, OBJ_H, ignoreId)) return { x: x, y: y };
115	      }
116	    }
117	    return { x: snap(region.x + region.w / 2 - OBJ_W / 2), y: snap(region.y + region.h / 2 - OBJ_H / 2) };
118	  }
119	  function selectedObjects() {
120	    if (state.selMany) return state.objects.filter(function (o) { return state.selMany.indexOf(o.id) >= 0; });
121	    if (state.sel && state.sel.kind === "object") {
122	      var o = byId("object", state.sel.id);
123	      return o ? [o] : [];
124	    }
125	    return [];
126	  }
127	  function esc(s) {
128	    return String(s).replace(/[&<>"']/g, function (c) {
129	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
130	    });
131	  }
