133	  // ---------- persistence (courtesy, never a loading state) ----------
134	  function save() {
135	    try {
136	      localStorage.setItem(STORE_KEY, JSON.stringify({
137	        v: 1, seq: state.seq, regions: state.regions, objects: state.objects, snap: state.snap
138	      }));
139	      if (!state.storageOK) { state.storageOK = true; renderStatus(); }
140	    } catch (e) {
141	      if (state.storageOK) { state.storageOK = false; renderStatus(); }
142	    }
143	  }
144	  var saveDebounced = null;
145	  function queueSave() {
146	    if (saveDebounced) clearTimeout(saveDebounced);
147	    saveDebounced = setTimeout(save, 250);
148	  }
149	  function load() {
150	    var fresh = scene();
151	    try {
152	      var raw = localStorage.getItem(STORE_KEY);
153	      if (!raw) { applyScene(fresh); return; }
154	      var data = JSON.parse(raw);
155	      if (!data || data.v !== 1 || !Array.isArray(data.regions) || !Array.isArray(data.objects)) {
156	        applyScene(fresh); return;
157	      }
158	      state.seq = data.seq || 1000;
159	      state.regions = data.regions;
160	      state.objects = data.objects;
161	      state.snap = !!data.snap;
162	    } catch (e) {
163	      state.storageOK = false;
164	      applyScene(fresh);
165	    }
166	  }
167	  function applyScene(s) {
168	    state.seq = s.seq;
169	    state.regions = JSON.parse(JSON.stringify(s.regions));
170	    state.objects = JSON.parse(JSON.stringify(s.objects));
171	  }
