173	  // ---------- view ----------
174	  function applyView() {
175	    world.style.transform = "translate(" + state.panX + "px," + state.panY + "px) scale(" + state.zoom + ")";
176	    viewport.style.backgroundSize =
177	      (G * 5 * state.zoom) + "px " + (G * 5 * state.zoom) + "px," +
178	      (G * 5 * state.zoom) + "px " + (G * 5 * state.zoom) + "px," +
179	      (G * state.zoom) + "px " + (G * state.zoom) + "px," +
180	      (G * state.zoom) + "px " + (G * state.zoom) + "px";
181	    viewport.style.backgroundPosition =
182	      state.panX + "px " + state.panY + "px," + state.panX + "px " + state.panY + "px," +
183	      state.panX + "px " + state.panY + "px," + state.panX + "px " + state.panY + "px";
184	    if (btnZoomLabel) btnZoomLabel.textContent = Math.round(state.zoom * 100) + "%";
185	  }
186	  function contentBBox() {
187	    var x1 = Infinity, y1 = Infinity, x2 = -Infinity, y2 = -Infinity, any = false;
188	    function acc(x, y, w, h) {
189	      any = true;
190	      x1 = Math.min(x1, x); y1 = Math.min(y1, y);
191	      x2 = Math.max(x2, x + w); y2 = Math.max(y2, y + h);
192	    }
193	    state.regions.forEach(function (r) { acc(r.x, r.y, r.w, r.h); });
194	    state.objects.forEach(function (o) { acc(o.x, o.y, OBJ_W, OBJ_H); });
195	    return any ? { x: x1, y: y1, w: x2 - x1, h: y2 - y1 } : { x: 0, y: 0, w: 800, h: 600 };
196	  }
197	  function fitView() {
198	    var b = contentBBox();
199	    var vw = viewport.clientWidth, vh = viewport.clientHeight;
200	    var z = Math.min((vw - 80) / b.w, (vh - 80) / b.h);
201	    z = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, z));
202	    state.zoom = z;
203	    state.panX = (vw - b.w * z) / 2 - b.x * z;
204	    state.panY = (vh - b.h * z) / 2 - b.y * z;
205	    applyView();
206	  }
207	  function zoomAt(cx, cy, factor) {
208	    var z2 = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, state.zoom * factor));
209	    var k = z2 / state.zoom;
210	    state.panX = cx - (cx - state.panX) * k;
211	    state.panY = cy - (cy - state.panY) * k;
212	    state.zoom = z2;
213	    applyView();
214	    renderStatus();
215	  }
216	  function panBy(dx, dy) {
217	    state.panX += dx; state.panY += dy;
218	    applyView();
219	  }
220	  function toWorld(clientX, clientY) {
221	    var r = viewport.getBoundingClientRect();
222	    return { x: (clientX - r.left - state.panX) / state.zoom, y: (clientY - r.top - state.panY) / state.zoom };
223	  }
224	  function worldToScreen(x, y) {
225	    var r = viewport.getBoundingClientRect();
226	    return { x: r.left + x * state.zoom + state.panX, y: r.top + y * state.zoom + state.panY };
227	  }
228	  function ensureVisible(el) {
229	    var r = viewport.getBoundingClientRect();
230	    var p1 = worldToScreen(el.x, el.y), p2 = worldToScreen(el.x + (el.w || OBJ_W), el.y + (el.h || OBJ_H));
231	    var m = 70;
232	    if (p2.x < r.left + m) state.panX += (r.left + m - p2.x);
233	    if (p1.x > r.right - m) state.panX -= (p1.x - (r.right - m));
234	    if (p2.y < r.top + m) state.panY += (r.top + m - p2.y);
235	    if (p1.y > r.bottom - m) state.panY -= (p1.y - (r.bottom - m));
236	    applyView();
237	  }
