239	  // ---------- selection ----------
240	  function select(kind, id) {
241	    state.sel = id ? { kind: kind, id: id } : null;
242	    state.selMany = null;
243	    state.landing = null;
244	    render();
245	  }
246	  function selectAllObjects() {
247	    if (!state.objects.length) return;
248	    state.selMany = state.objects.map(function (o) { return o.id; });
249	    state.sel = { kind: "object", id: state.selMany[0] };
250	    render();
251	    flash(state.objects.length + " tiles selected — arrows nudge all · 1–8 send all · Del removes");
252	  }
253	  function cycleSelection(dir) {
254	    var objs = state.objects;
255	    if (!objs.length) return;
256	    var idx = 0;
257	    if (state.sel && state.sel.kind === "object") {
258	      for (var i = 0; i < objs.length; i++) if (objs[i].id === state.sel.id) idx = i;
259	      idx = (idx + dir + objs.length) % objs.length;
260	    } else if (dir < 0) {
261	      idx = objs.length - 1;
262	    }
263	    var o = objs[idx];
264	    state.selMany = null;
265	    state.sel = { kind: "object", id: o.id };
266	    ensureVisible(o);
267	    render();
268	  }
