270	  // ---------- mutations ----------
271	  function commitPlacing() {
272	    if (!state.placing) return;
273	    var p = state.placing;
274	    var item;
275	    if (p.kind === "region") {
276	      item = { id: "z" + (state.seq++), name: "Zone " + (state.regions.length + 1), x: p.x, y: p.y, w: REGION_W, h: REGION_H };
277	      state.regions.push(item);
278	    } else {
279	      item = { id: "o" + (state.seq++), name: "Tile " + (state.objects.length + 1), x: p.x, y: p.y };
280	      state.objects.push(item);
281	    }
282	    state.placing = null;
283	    state.selMany = null;
284	    state.sel = { kind: p.kind === "region" ? "region" : "object", id: item.id };
285	    queueSave();
286	    render();
287	    startRename(state.sel.kind, item.id);
288	    flash("Placed — 落位即意图. Name it:");
289	  }
290	  function startPlace(kind) {
291	    cancelRename(false);
292	    var vw = viewport.clientWidth, vh = viewport.clientHeight;
293	    var c = { x: (vw / 2 - state.panX) / state.zoom, y: (vh / 2 - state.panY) / state.zoom };
294	    state.placing = { kind: kind, x: snap(c.x - (kind === "region" ? REGION_W : OBJ_W) / 2), y: snap(c.y - (kind === "region" ? REGION_H : OBJ_H) / 2) };
295	    updateLanding();
296	    render();
297	  }
298	  function movePlacing(dx, dy) {
299	    var p = state.placing;
300	    if (!p) return;
301	    p.x = snap(p.x + dx); p.y = snap(p.y + dy);
302	    updateLanding();
303	    renderGhostAndLanding();
304	    renderStatus();
305	  }
306	  function updateLanding() {
307	    var target = null;
308	    if (state.placing) {
309	      var s = state.placing.kind === "region" ? { w: REGION_W, h: REGION_H } : { w: OBJ_W, h: OBJ_H };
310	      target = zoneAt(state.placing.x + s.w / 2, state.placing.y + s.h / 2);
311	    } else {
312	      var objs = selectedObjects();
313	      if (objs.length) { var c = centerOf(objs[0]); target = zoneAt(c.x, c.y); }
314	    }
315	    state.landing = target ? target.id : null;
316	  }
317	  function nudge(dx, dy, coarse) {
318	    var step = state.snap ? G : 1;
319	    if (coarse) step *= 5;
320	    // regions move with arrows too (keyboard parity for every spatial op)
321	    if (state.sel && state.sel.kind === "region") {
322	      var r = byId("region", state.sel.id);
323	      if (r) {
324	        r.x = snap(r.x + dx * step); r.y = snap(r.y + dy * step);
325	        updateLanding(); ensureVisible(r); queueSave(); render();
326	      }
327	      return;
328	    }
329	    var objs = selectedObjects();
330	    if (!objs.length) { panBy(dx * 40, dy * 40); return; }
331	    objs.forEach(function (o) { o.x = snap(o.x + dx * step); o.y = snap(o.y + dy * step); });
332	    updateLanding();
333	    ensureVisible(objs[0]);
334	    queueSave();
335	    render();
336	  }
337	  function duplicateSelection() {
338	    var objs = selectedObjects();
339	    if (objs.length !== 1) return;
340	    var src = objs[0];
341	    var x = snap(src.x + G + G / 2), y = snap(src.y + G + G / 2), tries = 0;
342	    while (overlaps(x, y, OBJ_W, OBJ_H, null) && tries++ < 40) { x = snap(x + G); if (tries % 8 === 0) { x = snap(src.x); y = snap(y + G); } }
343	    var copy = { id: "o" + (state.seq++), name: src.name + " copy", x: x, y: y };
344	    state.objects.push(copy);
345	    state.selMany = null;
346	    state.sel = { kind: "object", id: copy.id };
347	    ensureVisible(copy);
348	    queueSave();
349	    render();
350	    flash("Duplicated — " + copy.name);
351	  }
352	  function deleteSelection() {
353	    if (state.selMany) {
354	      var ids = state.selMany;
355	      state.objects = state.objects.filter(function (o) { return ids.indexOf(o.id) < 0; });
356	      state.sel = null; state.selMany = null;
357	      queueSave(); render();
358	      flash(ids.length + " tiles removed");
359	      return;
360	    }
361	    if (!state.sel) return;
362	    if (state.sel.kind === "region") {
363	      var r = byId("region", state.sel.id);
364	      state.regions = state.regions.filter(function (z) { return z.id !== r.id; });
365	      flash('Zone "' + r.name + '" removed — its tiles stay on the floor');
366	    } else {
367	      var o = byId("object", state.sel.id);
368	      state.objects = state.objects.filter(function (t) { return t.id !== o.id; });
369	      flash('Tile "' + o.name + '" removed');
370	    }
371	    state.sel = null;
372	    queueSave(); render();
373	  }
374	  function sendToZone(idx) {
375	    var region = state.regions[idx];
376	    var objs = selectedObjects();
377	    if (!region) { flash("No zone " + (idx + 1)); return; }
378	    if (!objs.length) { flash("Select a tile first (Tab), then press " + (idx + 1)); return; }
379	    objs.forEach(function (o) {
380	      var slot = findSlot(region, o.id);
381	      o.x = slot.x; o.y = slot.y;
382	    });
383	    state.selMany = null;
384	    state.sel = { kind: "object", id: objs[0].id };
385	    ensureVisible(objs[0]);
386	    queueSave(); render();
387	    flash("Sent to " + region.name + " — " + (zoneOf(objs[0]) === region ? "membership derived ✓" : "no room, landed beside it"));
388	  }
389	  function reorder(dir) {
390	    if (!state.sel || state.sel.kind !== "object") return;
391	    var o = byId("object", state.sel.id);
392	    var i = state.objects.indexOf(o);
393	    state.objects.splice(i, 1);
394	    if (dir > 0) state.objects.push(o); else state.objects.unshift(o);
395	    queueSave(); render();
396	  }
