398	  // ---------- rename ----------
399	  function startRename(kind, id) {
400	    cancelRename(false);
401	    var el = document.querySelector('.tile[data-id="' + id + '"], .zone-chip[data-id="' + id + '"]');
402	    var item = byId(kind, id);
403	    if (!el || !item) return;
404	    var rect = el.getBoundingClientRect();
405	    var input = document.createElement("input");
406	    input.className = "rename-input";
407	    input.value = item.name;
408	    input.setAttribute("aria-label", "Rename " + item.name);
409	    var pw = rect.width, ph = Math.max(28, rect.height);
410	    input.style.left = rect.left + "px";
411	    input.style.top = rect.top + (rect.height - ph) / 2 + "px";
412	    input.style.width = pw + "px";
413	    input.style.height = ph + "px";
414	    document.body.appendChild(input);
415	    input.focus();
416	    input.select();
417	    state.renaming = { kind: kind, id: id, input: input };
418	    input.addEventListener("keydown", function (e) {
419	      e.stopPropagation();
420	      if (e.key === "Enter") { e.preventDefault(); cancelRename(true); }
421	      else if (e.key === "Escape") { e.preventDefault(); cancelRename(false); }
422	    });
423	    input.addEventListener("blur", function () { if (state.renaming) cancelRename(true); });
424	  }
425	  function cancelRename(apply) {
426	    var r = state.renaming;
427	    if (!r) return;
428	    state.renaming = null;
429	    var val = r.input.value.trim();
430	    r.input.remove();
431	    if (apply && val) {
432	      var item = byId(r.kind, r.id);
433	      if (item) item.name = val;
434	      queueSave();
435	    }
436	    render();
437	  }
