2	   A spatial workspace: land objects into zones; position is the only source of truth.
3	   Every spatial operation has a keyboard equivalent (acceptance seed). */
4	(function () {
5	  "use strict";
6	
7	  // ---------- constants ----------
8	  var G = 20;             // grid unit (world px)
