67	  // ---------- helpers ----------
68	  function snap(v) { return state.snap ? Math.round(v / G) * G : Math.round(v); }
69	  function byId(kind, id) {
70	    var arr = kind === "region" ? state.regions : state.objects;
71	    for (var i = 0; i < arr.length; i++) if (arr[i].id === id) return arr[i];
72	    return null;
73	  }
74	  function objSize() { return { w: OBJ_W, h: OBJ_H }; }
75	  function centerOf(o) {
76	    var s = o.w ? o : { w: OBJ_W, h: OBJ_H };
77	    return { x: o.x + s.w / 2, y: o.y + s.h / 2 };
78	  }
79	  function zoneAt(cx, cy) {
80	    for (var i = 0; i < state.regions.length; i++) {
81	      var r = state.regions[i];
82	      if (cx >= r.x && cx <= r.x + r.w && cy >= r.y && cy <= r.y + r.h) return r;
83	    }
84	    return null;
85	  }
86	  function zoneOf(o) { var c = centerOf(o); return zoneAt(c.x, c.y); }
87	  function zoneColor(i) { return PALETTE[i % PALETTE.length]; }
88	  function zoneIndex(id) {
89	    for (var i = 0; i < state.regions.length; i++) if (state.regions[i].id === id) return i;
90	    return -1;
91	  }
92	  function nearestTo(o) {
93	    var c1 = centerOf(o), best = null, bd = Infinity;
94	    for (var i = 0; i < state.objects.length; i++) {
95	      var t = state.objects[i];
96	      if (t.id === o.id) continue;
97	      var c2 = centerOf(t);
98	      var d = Math.hypot(c2.x - c1.x, c2.y - c1.y);
99	      if (d < bd) { bd = d; best = t; }
100	    }
101	    return best ? { obj: best, dist: bd } : null;
102	  }
103	  function overlaps(x, y, w, h, ignoreId) {
104	    for (var i = 0; i < state.objects.length; i++) {
105	      var o = state.objects[i];
106	      if (o.id === ignoreId) continue;
107	      if (x < o.x + OBJ_W && x + w > o.x && y < o.y + OBJ_H && y + h > o.y) return true;
108	    }
109	    return false;
110	  }
111	  function findSlot(region, ignoreId) {
112	    for (var y = region.y + G; y + OBJ_H <= region.y + region.h - G / 2; y += G) {
113	      for (var x = region.x + G; x + OBJ_W <= region.x + region.w - G / 2; x += G) {
114	        if (!overlaps(x, y, OBJ_W, OBJ_H, ignoreId)) return { x: x, y: y };
115	      }
116	    }
117	    return { x: snap(region.x + region.w / 2 - OBJ_W / 2), y: snap(region.y + region.h / 2 - OBJ_H / 2) };
118	  }
119	  function selectedObjects() {
120	    if (state.selMany) return state.objects.filter(function (o) { return state.selMany.indexOf(o.id) >= 0; });
121	    if (state.sel && state.sel.kind === "object") {
122	      var o = byId("object", state.sel.id);
123	      return o ? [o] : [];
124	    }
125	    return [];
126	  }
127	  function esc(s) {
128	    return String(s).replace(/[&<>"']/g, function (c) {
129	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
130	    });
131	  }
