934	      var b = e.target.closest("button[data-act]");
935	      if (!b) return;
936	      if (b.getAttribute("data-act") === "delete") deleteSelection();
937	      if (b.getAttribute("data-act") === "duplicate") duplicateSelection();
938	      if (b.getAttribute("data-act") === "rename" && state.sel) startRename(state.sel.kind, state.sel.id);
939	    });
940	
941	    // toolbar — every action hands focus back to the canvas so shortcuts keep flowing
942	    function refocus() { viewport.focus({ preventScroll: true }); }
943	    $("btnNewObject").addEventListener("click", function () { startPlace("object"); refocus(); });
944	    $("btnNewZone").addEventListener("click", function () { startPlace("region"); refocus(); });
945	    btnSnap.addEventListener("click", function () {
946	      state.snap = !state.snap; renderToolbar(); renderStatus(); refocus();
947	    });
948	    $("btnZoomIn").addEventListener("click", function () { zoomAt(viewport.clientWidth / 2, viewport.clientHeight / 2, 1.2); refocus(); });
949	    $("btnZoomOut").addEventListener("click", function () { zoomAt(viewport.clientWidth / 2, viewport.clientHeight / 2, 1 / 1.2); refocus(); });
950	    btnZoomLabel.addEventListener("click", function () { fitView(); refocus(); });
951	    $("btnFit").addEventListener("click", function () { fitView(); refocus(); });
