      renderLandingOnly();
    } else if (state.placing) {
      var p = state.placing;
      var s = p.kind === "region" ? { w: REGION_W, h: REGION_H } : { w: OBJ_W, h: OBJ_H };
      p.x = snap(wpt.x - s.w / 2); p.y = snap(wpt.y - s.h / 2);
