   Every spatial operation has a keyboard equivalent (acceptance seed). */
(function () {
  "use strict";

  // ---------- constants ----------
  var G = 20;             // grid unit (world px)
  var OBJ_W = 96, OBJ_H = 64;
  var REGION_W = 360, REGION_H = 240;
  var ZOOM_MIN = 0.25, ZOOM_MAX = 2.5;
  var STORE_KEY = "plotboard.v1";
